     1	package com.marealta.pousada.domain;
     2	
     3	import com.marealta.pousada.persistence.ReservationRepository;
     4	
     5	import java.math.BigDecimal;
     6	import java.time.LocalDate;
     7	import java.time.YearMonth;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	public final class ReportService {
    12	    private final ReservationRepository reservations;
    13	    private final RoomCatalog rooms;
    14	
    15	    public ReportService(ReservationRepository reservations, RoomCatalog rooms) {
    16	        this.reservations = reservations;
    17	        this.rooms = rooms;
    18	    }
    19	
    20	    public String occupancy(LocalDate night) {
    21	        List<Reservation> occupying = reservations.findOverlapping(night, night.plusDays(1)).stream()
    22	                .filter(r -> r.status().isPaid() && r.occupiesNight(night))
    23	                .sorted(Comparator.comparingInt(Reservation::roomNumber))
    24	                .toList();
    25	        List<List<String>> rows = occupying.stream().map(r -> List.of(
    26	                String.valueOf(r.roomNumber()), rooms.find(r.roomNumber()).orElseThrow().type().name(),
    27	                String.valueOf(r.id()), r.checkIn().toString(), r.checkOut().toString())).toList();
    28	        return Csv.render(List.of("room", "type", "reservation", "check_in", "check_out"), rows,
    29	                List.of("total", occupying.size() + "/" + rooms.all().size()));
    30	    }
    31	
    32	    public String revenue(YearMonth month) {
    33	        List<Reservation> kept = reservations.findByCheckInBetween(month.atDay(1), month.atEndOfMonth()).stream()
    34	                .filter(r -> r.kept().signum() > 0)
    35	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id))
    36	                .toList();
    37	        List<List<String>> rows = kept.stream().map(r -> List.of(
    38	                String.valueOf(r.id()), String.valueOf(r.roomNumber()), r.checkIn().toString(),
    39	                r.checkOut().toString(), r.status().name(), r.kept().toPlainString())).toList();
    40	        BigDecimal total = kept.stream().map(Reservation::kept).reduce(Money.ZERO, BigDecimal::add);
    41	        return Csv.render(List.of("reservation", "room", "check_in", "check_out", "status", "amount"), rows,
    42	                List.of("total", total.toPlainString()));
    43	    }
    44	}
