     7	public record ReservationDocument(String title, long reservationId, String guestName, String guestCpf,
     8	                                  int roomNumber, RoomType roomType, LocalDate checkIn, LocalDate checkOut,
     9	                                  int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    10	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    11	
    12	    public static ReservationDocument of(Reservation reservation, Room room) {
    13	        Quote quote = reservation.quote();
    14	        return new ReservationDocument("Comprovante de reserva", reservation.id(), reservation.guestName(),
    15	                reservation.guestCpf(), room.number(), room.type(), reservation.checkIn(), reservation.checkOut(),
    16	                quote.nights(), quote.subtotal(), quote.discount(), quote.total());
    17	    }
    18	
    19	    /** Texto do comprovante, usado no e-mail de confirmação. */
    20	    public String text() {
    21	        StringBuilder text = new StringBuilder();
    22	        text.append(title).append(" nº ").append(reservationId).append('\n');
    23	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
    24	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    25	        text.append("Entrada: ").append(DATE.format(checkIn)).append(" | Saída: ").append(DATE.format(checkOut))
    26	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    27	        text.append("Diárias: ").append(Money.format(subtotal)).append('\n');
    28	        if (discount.signum() > 0) {
    29	            text.append("Desconto: ").append(Money.format(discount)).append('\n');
    30	        }
    31	        text.append("Total: ").append(Money.format(total));
    32	        return text.toString();
    33	    }
    34	}
