     7	import static com.marealta.pousada.domain.ReservationStatus.*;
     8	
     9	public final class Reservation {
    10	    private long id;
    11	    private final int roomNumber;
    12	    private final String guestName;
    13	    private final String guestEmail;
    14	    private final String guestCpf;
    15	    private final LocalDate checkIn;
    16	    private final LocalDate checkOut;
    17	    private final int guests;
    18	    private final RatePlan ratePlan;
    19	    private final Quote quote;
    20	    private ReservationStatus status;
    21	    private BigDecimal amountPaid;
    22	    private BigDecimal refund;
    23	
    24	    public Reservation(long id, int roomNumber, String guestName, String guestEmail, String guestCpf,
    25	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan, Quote quote,
    26	                       ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
    27	        this.id = id;
    28	        this.roomNumber = roomNumber;
    29	        this.guestName = guestName;
    30	        this.guestEmail = guestEmail;
    31	        this.guestCpf = guestCpf;
    32	        this.checkIn = checkIn;
    33	        this.checkOut = checkOut;
    34	        this.guests = guests;
    35	        this.ratePlan = ratePlan;
    36	        this.quote = quote;
    37	        this.status = status;
    38	        this.amountPaid = amountPaid;
    39	        this.refund = refund;
    40	    }
    41	
    42	    public static Reservation open(NewReservation request, Quote quote) {
    43	        return new Reservation(0, request.roomNumber(), request.guestName(), request.guestEmail(),
    44	                request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(), request.ratePlan(),
    45	                quote, PENDING, Money.ZERO, null);
    46	    }
    47	
    48	    public void confirm() {
    49	        require(PENDING);
    50	        status = CONFIRMED;
    51	        amountPaid = quote.total();
    52	    }
    53	
    54	    public void registerCheckIn() {
    55	        require(CONFIRMED);
    56	        status = CHECKED_IN;
    57	    }
    58	
    59	    public void registerCheckOut() {
    60	        require(CHECKED_IN);
    61	        status = CHECKED_OUT;
    62	    }
    63	
    64	    public void cancel() {
    65	        require(PENDING, CONFIRMED);
    66	        status = CANCELLED;
    67	        refund = ratePlan.refundOf(amountPaid);
    68	    }
    69	
    70	    private void require(ReservationStatus... allowed) {
    71	        if (!Arrays.asList(allowed).contains(status)) {
    72	            throw new DomainException(ErrorCode.OPERATION_NOT_ALLOWED,
    73	                    "Operação não permitida para reserva com status " + status);
    74	        }
    75	    }
    76	
    77	    /** O que ficou com a pousada: pago menos devolvido. */
    78	    public BigDecimal kept() {
    79	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    80	    }
    81	
    82	    public boolean occupiesNight(LocalDate night) {
    83	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
    84	    }
    85	
    86	    public void assignId(long id) {
    87	        this.id = id;
    88	    }
    89	
