     1	package com.marealta.pousada.domain;
     2	
     3	import com.marealta.pousada.mail.MailService;
     4	import com.marealta.pousada.persistence.ReservationRepository;
     5	
     6	public final class ReservationService {
     7	    private final ReservationRepository reservations;
     8	    private final RoomCatalog rooms;
     9	    private final MailService mail;
    10	
    11	    public ReservationService(ReservationRepository reservations, RoomCatalog rooms, MailService mail) {
    12	        this.reservations = reservations;
    13	        this.rooms = rooms;
    14	        this.mail = mail;
    15	    }
    16	
    17	    public synchronized Reservation create(NewReservation request) {
    18	        if (!request.checkOut().isAfter(request.checkIn())) {
    19	            throw new DomainException(ErrorCode.INVALID_REQUEST, "A saída deve ser depois da entrada");
    20	        }
    21	        if (request.guests() < 1) {
    22	            throw new DomainException(ErrorCode.INVALID_REQUEST, "A reserva precisa de pelo menos um hóspede");
    23	        }
    24	        Room room = room(request.roomNumber());
    25	        if (request.guests() > room.capacity()) {
    26	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    27	                    "O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
    28	        }
    29	        if (!reservations.findActiveOverlapping(room.number(), request.checkIn(), request.checkOut()).isEmpty()) {
    30	            throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    31	                    "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    32	        }
    33	        Quote quote = Quote.of(room.type(), request.ratePlan(), request.checkIn(), request.checkOut());
    34	        Reservation reservation = Reservation.open(request, quote);
    35	        reservation.assignId(reservations.insert(reservation));
    36	        return reservation;
    37	    }
    38	
    39	    public Reservation find(long id) {
    40	        return reservations.find(id).orElseThrow(() ->
    41	                new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não encontrada"));
    42	    }
    43	
    44	    public synchronized Reservation confirm(long id) {
    45	        Reservation reservation = find(id);
    46	        reservation.confirm();
    47	        reservations.update(reservation);
    48	        mail.sendEmail(reservation.guestEmail(), "Reserva confirmada - Pousada Maré Alta", confirmationText(reservation));
    49	        return reservation;
    50	    }
    51	
    52	    public synchronized Reservation cancel(long id) {
    53	        Reservation reservation = find(id);
    54	        reservation.cancel();
    55	        reservations.update(reservation);
    56	        return reservation;
    57	    }
    58	
    59	    public synchronized Reservation checkIn(long id) {
    60	        Reservation reservation = find(id);
    61	        reservation.registerCheckIn();
    62	        reservations.update(reservation);
    63	        return reservation;
    64	    }
    65	
    66	    public synchronized ReservationDocument checkOut(long id) {
    67	        Reservation reservation = find(id);
    68	        reservation.registerCheckOut();
    69	        reservations.update(reservation);
    70	        return documentOf(reservation);
    71	    }
    72	
    73	    /** Segunda via do comprovante; só existe para reserva paga. */
    74	    public ReservationDocument document(long id) {
    75	        Reservation reservation = find(id);
    76	        if (!reservation.status().isPaid()) {
    77	            throw new DomainException(ErrorCode.OPERATION_NOT_ALLOWED,
    78	                    "Não há comprovante para reserva com status " + reservation.status());
    79	        }
    80	        return documentOf(reservation);
    81	    }
    82	
    83	    private ReservationDocument documentOf(Reservation reservation) {
    84	        return ReservationDocument.of(reservation, room(reservation.roomNumber()));
    85	    }
    86	
    87	    private Room room(int number) {
    88	        return rooms.find(number).orElseThrow(() ->
    89	                new DomainException(ErrorCode.ROOM_NOT_FOUND, "Quarto " + number + " não existe"));
    90	    }
    91	
    92	    private String confirmationText(Reservation reservation) {
    93	        return "Olá, " + reservation.guestName() + "!\n\n"
    94	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    95	                + documentOf(reservation).text() + "\n\n"
    96	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    97	                + "Até breve!";
    98	    }
    99	}
