     6	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     7	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     8	
     9	    public static Quote of(RoomType type, RatePlan plan, LocalDate checkIn, LocalDate checkOut) {
    10	        BigDecimal subtotal = Money.ZERO;
    11	        int nights = 0;
    12	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    13	            subtotal = subtotal.add(nightPrice(type, night));
    14	            nights++;
    15	        }
    16	        subtotal = Money.round(subtotal);
    17	        BigDecimal discount = plan.discountOn(subtotal);
    18	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    19	    }
    20	
    21	    private static BigDecimal nightPrice(RoomType type, LocalDate night) {
    22	        BigDecimal rate = type.nightlyRate();
    23	        return Money.round(Season.isHigh(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    24	    }
    25	}
