    11	
    12	    public MailService(MessageRepository repository, List<ScopedRule> rules, boolean testMode) {
    13	        this.repository = repository;
    14	        this.rules = rules.stream().filter(r -> r.scope().appliesTo(testMode)).map(ScopedRule::rule).toList();
