    12	    static boolean isValid(String address) {
    13	        if (address == null || address.chars().anyMatch(Character::isWhitespace)) {
    14	            return false;
    15	        }
    16	        int at = address.indexOf('@');
    17	        if (at <= 0 || at != address.lastIndexOf('@')) {
    18	            return false;
    19	        }
    20	        String domain = address.substring(at + 1);
    21	        return domain.length() > 2 && domain.substring(1, domain.length() - 1).contains(".");
    22	    }
    23	}
