    17	    /** Conecta (esperando o banco subir, se preciso) e cria o que faltar. */
    18	    public static DataSource connect(String url, String user, String password) {
    19	        HikariConfig config = new HikariConfig();
    20	        config.setJdbcUrl(url);
    21	        config.setUsername(user);
    22	        config.setPassword(password);
    23	        config.setInitializationFailTimeout(-1);
    24	        HikariDataSource dataSource = new HikariDataSource(config);
    25	        for (int attempt = 1; ; attempt++) {
    26	            try {
    27	                createSchema(dataSource);
    28	                return dataSource;
    29	            } catch (SQLException e) {
    30	                if (attempt >= ATTEMPTS) {
    31	                    throw new IllegalStateException("Não foi possível preparar o banco de dados", e);
    32	                }
    33	                try {
    34	                    Thread.sleep(1000);
    35	                } catch (InterruptedException interrupted) {
    36	                    Thread.currentThread().interrupt();
    37	                    throw new IllegalStateException(interrupted);
    38	                }
    39	            }
    40	        }
    41	    }
