    17	    public synchronized void sendEmail(String to, String subject, String body) {
    18	        List<Message> outgoing = List.of(Message.email(to, subject, body));
    19	        for (MailRule rule : rules) {
    20	            List<Message> next = new ArrayList<>();
    21	            for (Message message : outgoing) {
    22	                if (message.isBlocked()) {
    23	                    next.add(message);
    24	                } else {
    25	                    next.addAll(rule.apply(message));
    26	                }
    27	            }
    28	            outgoing = next;
    29	        }
    30	        outgoing.forEach(repository::save);
    31	    }
