     6	import javax.sql.DataSource;
     7	import java.sql.Connection;
     8	import java.sql.SQLException;
     9	import java.sql.Statement;
    10	
    11	public final class Database {
    12	    private static final int ATTEMPTS = 30;
    13	
    14	    private Database() {
    15	    }
    16	
    17	    /** Conecta (esperando o banco subir, se preciso) e cria o que faltar. */
    18	    public static DataSource connect(String url, String user, String password) {
    19	        HikariConfig config = new HikariConfig();
    20	        config.setJdbcUrl(url);
    21	        config.setUsername(user);
    22	        config.setPassword(password);
    23	        config.setInitializationFailTimeout(-1);
    24	        HikariDataSource dataSource = new HikariDataSource(config);
    25	        for (int attempt = 1; ; attempt++) {
    26	            try {
    27	                createSchema(dataSource);
    28	                return dataSource;
    29	            } catch (SQLException e) {
    30	                if (attempt >= ATTEMPTS) {
    31	                    throw new IllegalStateException("Não foi possível preparar o banco de dados", e);
    32	                }
    33	                try {
    34	                    Thread.sleep(1000);
    35	                } catch (InterruptedException interrupted) {
    36	                    Thread.currentThread().interrupt();
    37	                    throw new IllegalStateException(interrupted);
    38	                }
    39	            }
    40	        }
    41	    }
    42	
    43	    public static void createSchema(DataSource dataSource) throws SQLException {
    44	        try (Connection connection = dataSource.getConnection(); Statement statement = connection.createStatement()) {
    45	            statement.execute("""
    46	                    CREATE TABLE IF NOT EXISTS reservations (
    47	                        id BIGSERIAL PRIMARY KEY,
    48	                        room_number INTEGER NOT NULL,
    49	                        guest_name VARCHAR(255) NOT NULL,
    50	                        guest_email VARCHAR(255) NOT NULL,
    51	                        guest_cpf VARCHAR(64) NOT NULL,
    52	                        check_in DATE NOT NULL,
    53	                        check_out DATE NOT NULL,
    54	                        guests INTEGER NOT NULL,
    55	                        rate_plan VARCHAR(32) NOT NULL,
    56	                        nights INTEGER NOT NULL,
    57	                        subtotal NUMERIC(12,2) NOT NULL,
    58	                        discount NUMERIC(12,2) NOT NULL,
    59	                        total NUMERIC(12,2) NOT NULL,
    60	                        status VARCHAR(32) NOT NULL,
    61	                        amount_paid NUMERIC(12,2) NOT NULL,
    62	                        refund NUMERIC(12,2)
    63	                    )""");
    64	            statement.execute("""
    65	                    CREATE TABLE IF NOT EXISTS messages (
    66	                        id BIGSERIAL PRIMARY KEY,
    67	                        channel VARCHAR(32) NOT NULL,
    68	                        recipient VARCHAR(512) NOT NULL,
    69	                        subject VARCHAR(1024) NOT NULL,
    70	                        body TEXT NOT NULL,
    71	                        status VARCHAR(32) NOT NULL
    72	                    )""");
    73	        }
