    22	    @Override
    23	    public long insert(Reservation r) {
    24	        String sql = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    25	                + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
    26	                + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
    27	        try (Connection c = dataSource.getConnection();
    28	             PreparedStatement s = c.prepareStatement(sql, new String[]{"id"})) {
    29	            s.setInt(1, r.roomNumber());
    30	            s.setString(2, r.guestName());
    31	            s.setString(3, r.guestEmail());
    32	            s.setString(4, r.guestCpf());
    33	            s.setObject(5, r.checkIn());
    34	            s.setObject(6, r.checkOut());
    35	            s.setInt(7, r.guests());
    36	            s.setString(8, r.ratePlan().name());
    37	            s.setInt(9, r.quote().nights());
    38	            s.setBigDecimal(10, r.quote().subtotal());
    39	            s.setBigDecimal(11, r.quote().discount());
    40	            s.setBigDecimal(12, r.quote().total());
    41	            s.setString(13, r.status().name());
    42	            s.setBigDecimal(14, r.amountPaid());
    43	            s.setBigDecimal(15, r.refund());
    44	            s.executeUpdate();
    45	            try (ResultSet keys = s.getGeneratedKeys()) {
    46	                keys.next();
    47	                return keys.getLong(1);
    48	            }
    49	        } catch (SQLException e) {
    50	            throw new IllegalStateException(e);
    51	        }
    52	    }
    53	
    54	    @Override
    55	    public void update(Reservation r) {
