    57	             PreparedStatement s = c.prepareStatement(
    58	                     "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    59	            s.setString(1, r.status().name());
    60	            s.setBigDecimal(2, r.amountPaid());
    61	            s.setBigDecimal(3, r.refund());
    62	            s.setLong(4, r.id());
    63	            s.executeUpdate();
    64	        } catch (SQLException e) {
    65	            throw new IllegalStateException(e);
