    74	    @Override
    75	    public List<Reservation> findActiveOverlapping(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    76	        return query("WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?", s -> {
    77	            s.setInt(1, roomNumber);
    78	            s.setObject(2, checkOut);
    79	            s.setObject(3, checkIn);
    80	        });
    81	    }
