    83	    @Override
    84	    public List<Reservation> findOverlapping(LocalDate checkIn, LocalDate checkOut) {
    85	        return query("WHERE check_in < ? AND check_out > ?", s -> {
    86	            s.setObject(1, checkOut);
    87	            s.setObject(2, checkIn);
    88	        });
    89	    }
