    91	    @Override
    92	    public List<Reservation> findByCheckInBetween(LocalDate from, LocalDate to) {
    93	        return query("WHERE check_in >= ? AND check_in <= ?", s -> {
    94	            s.setObject(1, from);
    95	            s.setObject(2, to);
    96	        });
    97	    }
    98	
    99	    private interface Binder {
   100	        void bind(PreparedStatement statement) throws SQLException;
   101	    }
   102	
   103	    private List<Reservation> query(String where, Binder binder) {
   104	        try (Connection c = dataSource.getConnection();
   105	             PreparedStatement s = c.prepareStatement("SELECT " + COLUMNS + " FROM reservations " + where + " ORDER BY id")) {
   106	            binder.bind(s);
   107	            try (ResultSet rs = s.executeQuery()) {
   108	                List<Reservation> found = new ArrayList<>();
   109	                while (rs.next()) {
   110	                    found.add(read(rs));
   111	                }
   112	                return found;
   113	            }
   114	        } catch (SQLException e) {
   115	            throw new IllegalStateException(e);
   116	        }
   117	    }
