   119	    private Reservation read(ResultSet rs) throws SQLException {
   120	        Quote quote = new Quote(rs.getInt("nights"), rs.getBigDecimal("subtotal"), rs.getBigDecimal("discount"),
   121	                rs.getBigDecimal("total"));
   122	        return new Reservation(rs.getLong("id"), rs.getInt("room_number"), rs.getString("guest_name"),
   123	                rs.getString("guest_email"), rs.getString("guest_cpf"), rs.getObject("check_in", LocalDate.class),
   124	                rs.getObject("check_out", LocalDate.class), rs.getInt("guests"),
   125	                RatePlan.valueOf(rs.getString("rate_plan")), quote, ReservationStatus.valueOf(rs.getString("status")),
   126	                rs.getBigDecimal("amount_paid"), rs.getBigDecimal("refund"));
